<script setup lang="ts">
import {ref,watch} from 'vue'
import {api} from './session'
import {useTableWidths} from './tableWidths'
const props=defineProps<{listingId:number}>(),widths=useTableWidths('ListingLog')
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref('')
let request=0
async function load(){const id=++request;loading.value=true;error.value='';try{const d=await api(`/listings/${props.listingId}/logs?page=${page.value}`);if(id===request){rows.value=d.rows;total.value=d.total}}catch(e){if(id===request)error.value=(e as Error).message}finally{if(id===request)loading.value=false}}
watch(()=>props.listingId,()=>{page.value=1;rows.value=[];load()},{immediate:true})
const statuses:Record<string,string>={saved:'已保存',queued:'排队中',submitting:'提交中',accepted:'已受理，待生效核对',verified:'回读已确认',rejected:'未接受',unknown:'结果待核对'}
const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
</script>
<template><div class="listing-log"><div class="log-toolbar"><span>调价、编辑和关联记录</span><el-button :loading="loading" @click="load">刷新日志</el-button><TableReset table-key="ListingLog/logs"/></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="true"><el-table :data="rows" v-loading="loading" row-key="id" border data-width-key="ListingLog/logs" @header-dragend="(w:number,_:number,c:any)=>widths.resize('logs',w,c)"><el-table-column prop="created_at" column-key="time" label="时间" :width="widths.width('logs','time',180)"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column prop="actor" column-key="actor" label="操作人" :width="widths.width('logs','actor',120)"/><el-table-column column-key="source" label="来源" :width="widths.width('logs','source',155)"><template #default="{row}">{{({web:'页面操作',token:'MCP / API',system:'系统',history:'历史记录'} as Record<string,string>)[row.source]||row.source}}<div v-if="row.token_id" class="muted">Token #{{row.token_id}}</div></template></el-table-column><el-table-column prop="action" column-key="action" label="操作" :width="widths.width('logs','action',130)"/><el-table-column column-key="status" label="结果" :width="widths.width('logs','status',180)"><template #default="{row}"><el-tag :type="row.status==='rejected'?'danger':row.status==='saved'||row.status==='verified'?'success':'info'">{{statuses[row.status]||row.status}}</el-tag><div class="log-message">{{row.message}}</div></template></el-table-column><el-table-column label="修改内容" min-width="320"><template #default="{row}"><details v-if="row.changes.length"><summary>{{row.changes.map((v:any)=>v.field).join('、')}} · 查看前后内容</summary><div v-for="(change,i) in row.changes" :key="i" class="log-change"><b>{{change.field}}</b><div><span class="muted">修改前：</span>{{change.before}}</div><div><span class="muted">修改后：</span>{{change.after}}</div></div></details><span v-else class="muted">{{row.source==='history'?'历史记录未保存修改明细':'无字段修改'}}</span></template></el-table-column><template #empty>暂无操作日志</template></el-table></template><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></div></template>
<style scoped>.log-toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.log-message{font-size:12px;line-height:1.6;margin-top:6px}.log-change{padding:10px 0;border-bottom:1px solid #e8efec;white-space:pre-wrap;overflow-wrap:anywhere}.log-change div{margin-top:5px}.listing-log summary{cursor:pointer;color:#217864}.el-pagination{margin-top:14px;justify-content:flex-end}</style>
